const express = require('express');
const { EventStoreDBClient, jsonEvent } = require('@eventstore/db-client');
const { jwtAuth } = require('../middleware/auth');
const { db } = require('../db');

const router = express.Router();
const client = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.post('/api/commands/wallet-transfer', jwtAuth, async (req, res) => {
  const { sourceWalletId, destinationWalletId, amount, currency } = req.body;

  const wallet = await db.query(
    'SELECT id FROM crypto_wallets WHERE id = $1 AND user_id = $2',
    [sourceWalletId, req.user.id]
  );
  if (!wallet.rows.length) {
    return res.status(403).json({ error: 'Access denied: you do not own the source wallet' });
  }

  const event = jsonEvent({
    type: 'WalletFundsTransferred',
    data: {
      sourceWalletId,
      destinationWalletId,
      amount,
      currency,
      initiatedBy: req.user.id,
      timestamp: new Date().toISOString(),
    },
  });

  await client.appendToStream(`wallet-${sourceWalletId}`, [event]);
  res.status(202).json({ status: 'command_accepted', stream: `wallet-${sourceWalletId}` });
});
